// Add custom rankings event listeners
document.addEventListener('DOMContentLoaded', function() {
    restore_options();
    
    // Custom rankings toggle
    const customRankingsEnabledEl = document.getElementById('customRankingsEnabled');
    if (customRankingsEnabledEl) {
        customRankingsEnabledEl.addEventListener('click', save_options);
    }
    
    // File import
    const importBtn = document.getElementById('importCustomRankings');
    if (importBtn) {
        importBtn.addEventListener('click', function() {
            const fileInput = document.getElementById('customRankingFile');
            const file = fileInput.files[0];
            if (file) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    processCustomRankingData(e.target.result, file.name.toLowerCase().endsWith('.json'));
                };
                reader.readAsText(file);
            }
        });
    }
    
    // Parse text data
    const parseBtn = document.getElementById('parseCustomRankings');
    if (parseBtn) {
        parseBtn.addEventListener('click', function() {
            const textArea = document.getElementById('customRankingText');
            const data = textArea.value.trim();
            if (data) {
                // Try to detect if it's JSON
                const isJson = data.startsWith('{') || data.startsWith('[');
                processCustomRankingData(data, isJson);
            }
        });
    }
    
    // Clear all custom rankings
    const clearBtn = document.getElementById('clearCustomRankings');
    if (clearBtn) {
        clearBtn.addEventListener('click', function() {
            if (confirm('Are you sure you want to clear all custom rankings?')) {
                clearCustomRankings();
            }
        });
    }
});

// Custom ranking management functions
function processCustomRankingData(data, isJson) {
    const statusEl = document.getElementById('customRankingStatus');
    
    try {
        let parsedData;
        if (typeof customRankings !== 'undefined') {
            if (isJson) {
                parsedData = customRankings.parseJSON(data);
            } else {
                parsedData = customRankings.parseCSV(data);
            }
            
            // Save the data
            customRankings.save(parsedData).then(function() {
                const count = Object.keys(parsedData).length;
                statusEl.textContent = `Successfully imported ${count} rankings`;
                statusEl.style.color = 'green';
                updateCustomRankingCount();
                
                // Clear the text area
                const textArea = document.getElementById('customRankingText');
                if (textArea) textArea.value = '';
                
                // Clear file input
                const fileInput = document.getElementById('customRankingFile');
                if (fileInput) fileInput.value = '';
                
            }).catch(function(error) {
                statusEl.textContent = 'Error saving rankings: ' + error.message;
                statusEl.style.color = 'red';
            });
        } else {
            statusEl.textContent = 'Custom rankings module not loaded';
            statusEl.style.color = 'red';
        }
    } catch (error) {
        statusEl.textContent = 'Error parsing data: ' + error.message;
        statusEl.style.color = 'red';
    }
}

function clearCustomRankings() {
    const statusEl = document.getElementById('customRankingStatus');
    
    if (typeof customRankings !== 'undefined') {
        customRankings.save({}).then(function() {
            statusEl.textContent = 'All custom rankings cleared';
            statusEl.style.color = 'green';
            updateCustomRankingCount();
        }).catch(function(error) {
            statusEl.textContent = 'Error clearing rankings: ' + error.message;
            statusEl.style.color = 'red';
        });
    }
}

function updateCustomRankingCount() {
    const countEl = document.getElementById('customRankingCount');
    if (countEl && typeof customRankings !== 'undefined') {
        customRankings.load().then(function(data) {
            const count = Object.keys(data || {}).length;
            countEl.textContent = count;
        });
    }
}


