getRankClass = function (ranks) {
    quarts = ["Q1", "Q2", "Q3", "Q4", "A", "B", "C", "D", "I", "II", "III"]
    if(ranks == "A+") {
        return "ccf-Aplus";
    } else if (ranks == "A/B") {
        return "ccf-b";
    } else if (ranks == "B/C") {
        return "ccf-c"; 
    } else if (ranks == "C/D") {
        return "ccf-d";    
    } else {
        for (let rank of quarts) {
            for (let r of ranks) {
                if (r == rank) {
                    return "ccf-" + rank.toLowerCase();
                }
            }
        }
    }        
    return "ccf-none"; 
};



